            below = [(i,j) for i in range(r+1,h) for j in range(w) if grid[i][j] != bg]
            if bool(above) == bool(below):
                continue
            obj = above if above else below
            rr = min(i for i,j in obj)-1 if above else max(i for i,j in obj)+1
            if 0 <= rr < h and all(grid[rr][c] == bg for c in range(w)):
                out[rr] = [8]*w
            return out
    for c in range(w):
        if all(grid[r][c] == 2 for r in range(h)):
            left = [(i,j) for i in range(h) for j in range(c) if grid[i][j] != bg]
            right = [(i,j) for i in range(h) for j in range(c+1,w) if grid[i][j] != bg]
